function getCookie(cookieString, name) {
  const pairs = cookieString.split("; ");
  const found = pairs.find((pair) => pair.startsWith(`${name}=`));
  return found ? found.slice(name.length + 1) : undefined; // everything after "name="
}

// In the browser, cookieString would come from document.cookie
const cookieString = "theme=dark; userId=42";
console.log(getCookie(cookieString, "userId")); // "42"

